import{j as t,b as e}from"./index-B8nEtxug.js";import{I as a}from"./InfoPage-CsPIinpj.js";import"./PageHeader-C76-gu-5.js";function o(){return t.jsx(a,{title:"Map and travel",lead:"Brightwell sits in the north of Lagos, twenty minutes from the international airport. Everything you need to find us, arrive and get around is below.",crumbs:[{to:"/",label:"Home"},{to:"/about",label:"About"},{label:"Map and travel"}],sections:[{heading:"Finding us",body:[`The University is at ${e.address}. The main entrance, the Broad Gate, is on Academic Way and is staffed around the clock.`,"The fastest route from the airport is the express corridor northbound; allow thirty minutes at quiet times and double it during rush hour."],aside:{title:"The campus",rows:[["Main entrance","Broad Gate, Academic Way"],["Information office","Beside the Broad Gate"],["Access","Step-free from the gate"],["Parking","Limited; permit needed"]],links:[["/visitors","Plan your visit"]]}},{heading:"Arriving by air, road and rail",body:["By air — the international airport is served by a direct coach to the campus coach stop, with taxis and app-based rides also waiting outside arrivals.","By road — the express corridor runs directly past the University; follow the brown signposts for Brightwell University.","By rail — two intercity services stop at Brightwell Central, a ten-minute walk or a short shuttle ride from the Broad Gate."],list:{title:"Local transport",items:["City buses stop outside the Broad Gate on a frequent service.","The shuttle between the central campus and the science quarter runs every ten minutes in term time.","Cycling is the most popular way around campus; bike stands are at every college gate."]}},{heading:"Parking and accessibility",body:["Car parking on the central campus is reserved for blue-badge holders and permit staff; visitor spaces are available at the Westgate car park, a short walk away. Drop-off points at the museums are step-free.","Our full access guide is available from the information office or online, with details of every step-free route and accessible toilet on campus."],aside:{title:"Contact for directions",rows:[["Information office",`${e.phone}`],["Email","visitors@brightwell.ng"],["Westgate parking","Pre-bookable"]],links:[["/contact","Contact us"],["/accessibility","Accessibility statement"]]}}]})}export{o as default};
